-- Increment 27 — seed data, hand-written (NOT generated by drizzle-kit).
--
-- WHY THIS FILE EXISTS: the SQLite migration chain carried its seeds inside
-- 0014_young_scorpion.sql. Increment 27 collapsed all 20 SQLite migrations into
-- one drizzle-kit-GENERATED Postgres baseline (0000_init_pg.sql) — and
-- drizzle-kit only ever emits DDL, never data. The seeds were therefore silently
-- dropped: a fresh Postgres deployment came up with an EMPTY done-rule matrix, so
-- every ticket classified as not-done and Closure/Capacity/dimming all reported
-- zero. Caught by the test suite before release; this file restores them.
--
-- Keep this separate from 0000_init_pg.sql: regenerating the baseline
-- (`pnpm --filter @osp/db db:generate`) overwrites that file, and the seeds must
-- survive it.
--
-- Idempotent on purpose — re-running it must never duplicate or clobber a value
-- the user has since edited.

-- Increment 14 (SPEC_14 §2) — the global done-rule matrix defaults.
-- Kept in exact sync with DEFAULT_DONE_RULES in packages/contracts/src/common.ts;
-- change both together if the defaults ever change.
INSERT INTO "done_rule" ("status_name", "kind") VALUES
	('Developed', 'always_done'),
	('Merge pending', 'always_done'),
	('Tested', 'always_done'),
	('Resolved', 'always_done'),
	('Closed', 'always_done'),
	('New', 'role_dependent'),
	('Confirmed', 'role_dependent'),
	('In progress', 'role_dependent'),
	('On hold', 'role_dependent'),
	('Rejected', 'rejected')
ON CONFLICT ("status_name") DO NOTHING;
--> statement-breakpoint
-- Increment 14 (SPEC_14 §3/§7 #5) — the singleton report_config row.
-- overshoot_threshold_pct falls back to the column DEFAULT (25), which is
-- DEFAULT_OVERSHOOT_THRESHOLD_PCT in packages/contracts/src/common.ts.
-- No setval needed here: done_rule.id is a serial and these INSERTs deliberately
-- omit it, so the sequence advances by itself; report_config.id is a plain
-- integer PK (the singleton, always 1) with no sequence at all. The JSON import
-- path is different — it loads EXPLICIT ids and must reset sequences afterwards.
-- See docs/INCREMENT_27_CONTRACTS.md §6.
INSERT INTO "report_config" ("id") VALUES (1)
ON CONFLICT ("id") DO NOTHING;
